body.script:

(function() {
  var iframe = document.getElementById('mainFrame');
  var doc = iframe.contentDocument || iframe.contentWindow.document;
  doc.open();
  doc.write('<!DOCTYPE html>\n');
  doc.write('<html>\n');
  doc.write('<head>\n');
  doc.write('  <meta charset="UTF-8">\n');
  doc.write('  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n');
  doc.write('  <title>Nex Game Platform</title>\n');
  doc.write('  <script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@f60df53fb5554e4e160c086b47bf71f6a213e42c/nex.min.js"><\/script>\n');
  doc.write('  <style>\n');
  doc.write('    * { margin: 0; padding: 0; box-sizing: border-box; }\n');
  doc.write('    body { \n');
  doc.write('      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n');
  doc.write('      background: #0a0a0f;\n');
  doc.write('      color: #fff;\n');
  doc.write('      min-height: 100vh;\n');
  doc.write('      overflow-y: auto;\n');
  doc.write('    }\n');
  doc.write('    .header {\n');
  doc.write('      background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);\n');
  doc.write('      padding: 30px 20px;\n');
  doc.write('      text-align: center;\n');
  doc.write('      border-bottom: 1px solid #2a2a4e;\n');
  doc.write('      position: sticky;\n');
  doc.write('      top: 0;\n');
  doc.write('      z-index: 100;\n');
  doc.write('    }\n');
  doc.write('    .header h1 {\n');
  doc.write('      font-size: 2.5rem;\n');
  doc.write('      font-weight: 800;\n');
  doc.write('      background: linear-gradient(135deg, #6366f1, #8b5cf6);\n');
  doc.write('      -webkit-background-clip: text;\n');
  doc.write('      -webkit-text-fill-color: transparent;\n');
  doc.write('      margin-bottom: 8px;\n');
  doc.write('    }\n');
  doc.write('    .header p { color: #888; font-size: 1.1rem; }\n');
  doc.write('    .container { max-width: 1400px; margin: 0 auto; padding: 20px; }\n');
  doc.write('    .controls {\n');
  doc.write('      display: flex;\n');
  doc.write('      gap: 10px;\n');
  doc.write('      flex-wrap: wrap;\n');
  doc.write('      margin-bottom: 20px;\n');
  doc.write('      padding: 15px;\n');
  doc.write('      background: #1a1a2e;\n');
  doc.write('      border-radius: 12px;\n');
  doc.write('      border: 1px solid #2a2a4e;\n');
  doc.write('    }\n');
  doc.write('    .controls input {\n');
  doc.write('      flex: 1;\n');
  doc.write('      min-width: 200px;\n');
  doc.write('      padding: 12px 16px;\n');
  doc.write('      background: #0a0a0f;\n');
  doc.write('      border: 1px solid #2a2a4e;\n');
  doc.write('      border-radius: 8px;\n');
  doc.write('      color: #fff;\n');
  doc.write('      font-size: 1rem;\n');
  doc.write('    }\n');
  doc.write('    .controls input:focus { outline: none; border-color: #6366f1; }\n');
  doc.write('    .controls input::placeholder { color: #555; }\n');
  doc.write('    .controls button {\n');
  doc.write('      padding: 12px 24px;\n');
  doc.write('      background: #6366f1;\n');
  doc.write('      color: #fff;\n');
  doc.write('      border: none;\n');
  doc.write('      border-radius: 8px;\n');
  doc.write('      cursor: pointer;\n');
  doc.write('      font-size: 1rem;\n');
  doc.write('      font-weight: 600;\n');
  doc.write('      transition: all 0.3s;\n');
  doc.write('      white-space: nowrap;\n');
  doc.write('    }\n');
  doc.write('    .controls button:hover {\n');
  doc.write('      background: #818cf8;\n');
  doc.write('      transform: translateY(-2px);\n');
  doc.write('      box-shadow: 0 4px 20px rgba(99, 102, 241, 0.3);\n');
  doc.write('    }\n');
  doc.write('    .controls button.secondary {\n');
  doc.write('      background: #1a1a2e;\n');
  doc.write('      border: 1px solid #2a2a4e;\n');
  doc.write('    }\n');
  doc.write('    .controls button.secondary:hover {\n');
  doc.write('      background: #2a2a4e;\n');
  doc.write('      box-shadow: none;\n');
  doc.write('    }\n');
  doc.write('    .game-wrapper {\n');
  doc.write('      background: #1a1a2e;\n');
  doc.write('      border-radius: 12px;\n');
  doc.write('      border: 1px solid #2a2a4e;\n');
  doc.write('      overflow: hidden;\n');
  doc.write('      margin-bottom: 20px;\n');
  doc.write('      position: relative;\n');
  doc.write('      aspect-ratio: 16/9;\n');
  doc.write('      min-height: 400px;\n');
  doc.write('      width: 100%;\n');
  doc.write('    }\n');
  doc.write('    .game-wrapper .loading-overlay {\n');
  doc.write('      position: absolute;\n');
  doc.write('      inset: 0;\n');
  doc.write('      display: flex;\n');
  doc.write('      flex-direction: column;\n');
  doc.write('      align-items: center;\n');
  doc.write('      justify-content: center;\n');
  doc.write('      background: #0a0a0f;\n');
  doc.write('      z-index: 10;\n');
  doc.write('      transition: opacity 0.5s;\n');
  doc.write('    }\n');
  doc.write('    .game-wrapper .loading-overlay.hidden {\n');
  doc.write('      opacity: 0;\n');
  doc.write('      pointer-events: none;\n');
  doc.write('    }\n');
  doc.write('    .game-wrapper .spinner {\n');
  doc.write('      width: 50px;\n');
  doc.write('      height: 50px;\n');
  doc.write('      border: 3px solid #2a2a4e;\n');
  doc.write('      border-top-color: #6366f1;\n');
  doc.write('      border-radius: 50%;\n');
  doc.write('      animation: spin 1s linear infinite;\n');
  doc.write('    }\n');
  doc.write('    .game-wrapper .progress-bar {\n');
  doc.write('      margin-top: 20px;\n');
  doc.write('      width: 200px;\n');
  doc.write('      height: 4px;\n');
  doc.write('      background: #2a2a4e;\n');
  doc.write('      border-radius: 2px;\n');
  doc.write('      overflow: hidden;\n');
  doc.write('    }\n');
  doc.write('    .game-wrapper .progress-bar .fill {\n');
  doc.write('      height: 100%;\n');
  doc.write('      background: linear-gradient(90deg, #6366f1, #8b5cf6);\n');
  doc.write('      width: 0%;\n');
  doc.write('      transition: width 0.3s;\n');
  doc.write('    }\n');
  doc.write('    .game-wrapper .loading-text {\n');
  doc.write('      margin-top: 12px;\n');
  doc.write('      color: #888;\n');
  doc.write('      font-size: 0.9rem;\n');
  doc.write('    }\n');
  doc.write('    @keyframes spin { to { transform: rotate(360deg); } }\n');
  doc.write('    nex-game { display: block; width: 100%; height: 100%; }\n');
  doc.write('    .status {\n');
  doc.write('      display: flex;\n');
  doc.write('      align-items: center;\n');
  doc.write('      gap: 10px;\n');
  doc.write('      color: #888;\n');
  doc.write('      font-size: 0.9rem;\n');
  doc.write('      padding: 10px 4px;\n');
  doc.write('      margin-bottom: 20px;\n');
  doc.write('    }\n');
  doc.write('    .status .dot {\n');
  doc.write('      width: 8px;\n');
  doc.write('      height: 8px;\n');
  doc.write('      border-radius: 50%;\n');
  doc.write('      display: inline-block;\n');
  doc.write('    }\n');
  doc.write('    .status .dot.loading { background: #f59e0b; animation: pulse 1.5s infinite; }\n');
  doc.write('    .status .dot.ready { background: #10b981; }\n');
  doc.write('    .status .dot.error { background: #ef4444; }\n');
  doc.write('    @keyframes pulse {\n');
  doc.write('      0%, 100% { opacity: 1; }\n');
  doc.write('      50% { opacity: 0.3; }\n');
  doc.write('    }\n');
  doc.write('    .error-message {\n');
  doc.write('      background: rgba(239, 68, 68, 0.1);\n');
  doc.write('      border: 1px solid rgba(239, 68, 68, 0.3);\n');
  doc.write('      color: #ef4444;\n');
  doc.write('      padding: 12px 16px;\n');
  doc.write('      border-radius: 8px;\n');
  doc.write('      margin-bottom: 16px;\n');
  doc.write('      display: none;\n');
  doc.write('    }\n');
  doc.write('    .error-message.visible { display: block; }\n');
  doc.write('    .gallery-section { margin-top: 30px; padding-bottom: 40px; }\n');
  doc.write('    .gallery-section h2 {\n');
  doc.write('      margin-bottom: 16px;\n');
  doc.write('      font-size: 1.5rem;\n');
  doc.write('      color: #e0e0e0;\n');
  doc.write('    }\n');
  doc.write('    .gallery-grid {\n');
  doc.write('      display: grid;\n');
  doc.write('      grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));\n');
  doc.write('      gap: 16px;\n');
  doc.write('    }\n');
  doc.write('    .gallery-card {\n');
  doc.write('      background: #1a1a2e;\n');
  doc.write('      border-radius: 10px;\n');
  doc.write('      overflow: hidden;\n');
  doc.write('      cursor: pointer;\n');
  doc.write('      transition: all 0.3s;\n');
  doc.write('      border: 1px solid transparent;\n');
  doc.write('    }\n');
  doc.write('    .gallery-card:hover {\n');
  doc.write('      transform: translateY(-4px);\n');
  doc.write('      border-color: #6366f1;\n');
  doc.write('      box-shadow: 0 8px 30px rgba(99, 102, 241, 0.15);\n');
  doc.write('    }\n');
  doc.write('    .gallery-card img {\n');
  doc.write('      width: 100%;\n');
  doc.write('      aspect-ratio: 4/3;\n');
  doc.write('      object-fit: cover;\n');
  doc.write('      display: block;\n');
  doc.write('    }\n');
  doc.write('    .gallery-card .info { padding: 10px 12px; }\n');
  doc.write('    .gallery-card .info h3 {\n');
  doc.write('      font-size: 0.9rem;\n');
  doc.write('      font-weight: 600;\n');
  doc.write('      margin-bottom: 2px;\n');
  doc.write('      white-space: nowrap;\n');
  doc.write('      overflow: hidden;\n');
  doc.write('      text-overflow: ellipsis;\n');
  doc.write('    }\n');
  doc.write('    .gallery-card .info .category {\n');
  doc.write('      font-size: 0.75rem;\n');
  doc.write('      color: #888;\n');
  doc.write('    }\n');
  doc.write('    ::-webkit-scrollbar {\n');
  doc.write('      width: 10px;\n');
  doc.write('      height: 10px;\n');
  doc.write('    }\n');
  doc.write('    ::-webkit-scrollbar-track {\n');
  doc.write('      background: #0a0a0f;\n');
  doc.write('    }\n');
  doc.write('    ::-webkit-scrollbar-thumb {\n');
  doc.write('      background: #2a2a4e;\n');
  doc.write('      border-radius: 5px;\n');
  doc.write('    }\n');
  doc.write('    ::-webkit-scrollbar-thumb:hover {\n');
  doc.write('      background: #6366f1;\n');
  doc.write('    }\n');
  doc.write('    @media (max-width: 768px) {\n');
  doc.write('      .header h1 { font-size: 1.8rem; }\n');
  doc.write('      .controls input { min-width: 140px; }\n');
  doc.write('      .controls button { padding: 10px 16px; font-size: 0.9rem; }\n');
  doc.write('      .gallery-grid { grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); }\n');
  doc.write('      .game-wrapper { aspect-ratio: auto; min-height: 300px; }\n');
  doc.write('    }\n');
  doc.write('    @media (max-width: 480px) {\n');
  doc.write('      .header h1 { font-size: 1.4rem; }\n');
  doc.write('      .gallery-grid { grid-template-columns: repeat(auto-fill, minmax(100px, 1fr)); }\n');
  doc.write('      .game-wrapper { min-height: 250px; }\n');
  doc.write('    }\n');
  doc.write('  <\/style>\n');
  doc.write('<\/head>\n');
  doc.write('<body>\n');
  doc.write('  <header class="header">\n');
  doc.write('    <h1>🎮 Nex Game Platform<\/h1>\n');
  doc.write('    <p>Kies een game of zoek naar een specifieke titel<\/p>\n');
  doc.write('  <\/header>\n');
  doc.write('  \n');
  doc.write('  <div class="container">\n');
  doc.write('    <div class="error-message" id="errorMessage">\n');
  doc.write('      ⚠️ <span id="errorText">Er is een fout opgetreden<\/span>\n');
  doc.write('    <\/div>\n');
  doc.write('    \n');
  doc.write('    <div class="controls">\n');
  doc.write('      <input type="text" id="searchInput" placeholder="Zoek een game..." oninput="filterGames(this.value)">\n');
  doc.write('      <button onclick="resetGame()">🔄 Reset<\/button>\n');
  doc.write('      <button onclick="loadRandomGame()" class="secondary">🎲 Willekeurig<\/button>\n');
  doc.write('    <\/div>\n');
  doc.write('    \n');
  doc.write('    <div class="game-wrapper" id="gameWrapper">\n');
  doc.write('      <div class="loading-overlay" id="loadingOverlay">\n');
  doc.write('        <div class="spinner"><\/div>\n');
  doc.write('        <div class="progress-bar">\n');
  doc.write('          <div class="fill" id="progressFill"><\/div>\n');
  doc.write('        <\/div>\n');
  doc.write('        <div class="loading-text" id="loadingText">Laden...<\/div>\n');
  doc.write('      <\/div>\n');
  doc.write('      <nex-game id="gameContainer" alias="2048" gid="main-game"><\/nex-game>\n');
  doc.write('    <\/div>\n');
  doc.write('    \n');
  doc.write('    <div class="status">\n');
  doc.write('      <span class="dot loading" id="statusDot"><\/span>\n');
  doc.write('      <span id="statusText">Laden...<\/span>\n');
  doc.write('    <\/div>\n');
  doc.write('    \n');
  doc.write('    <div class="gallery-section">\n');
  doc.write('      <h2>📚 Alle Games<\/h2>\n');
  doc.write('      <div class="gallery-grid" id="galleryGrid"><\/div>\n');
  doc.write('    <\/div>\n');
  doc.write('  <\/div>\n');
  doc.write('  \n');
  doc.write('  <script>\n');
  doc.write('    let currentGid = "main-game";\n');
  doc.write('    let currentAlias = "2048";\n');
  doc.write('    \n');
  doc.write('    const gameContainer = document.getElementById("gameContainer");\n');
  doc.write('    const loadingOverlay = document.getElementById("loadingOverlay");\n');
  doc.write('    const progressFill = document.getElementById("progressFill");\n');
  doc.write('    const loadingText = document.getElementById("loadingText");\n');
  doc.write('    const statusDot = document.getElementById("statusDot");\n');
  doc.write('    const statusText = document.getElementById("statusText");\n');
  doc.write('    const errorMessage = document.getElementById("errorMessage");\n');
  doc.write('    const errorText = document.getElementById("errorText");\n');
  doc.write('    const galleryGrid = document.getElementById("galleryGrid");\n');
  doc.write('    const searchInput = document.getElementById("searchInput");\n');
  doc.write('    \n');
  doc.write('    function setStatus(state, message) {\n');
  doc.write('      statusDot.className = "dot";\n');
  doc.write('      if (state === "loading") {\n');
  doc.write('        statusDot.classList.add("loading");\n');
  doc.write('        statusText.textContent = message || "Laden...";\n');
  doc.write('      } else if (state === "ready") {\n');
  doc.write('        statusDot.classList.add("ready");\n');
  doc.write('        statusText.textContent = message || "Klaar om te spelen!";\n');
  doc.write('      } else if (state === "error") {\n');
  doc.write('        statusDot.classList.add("error");\n');
  doc.write('        statusText.textContent = message || "Fout";\n');
  doc.write('      }\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    function showError(msg) {\n');
  doc.write('      errorText.textContent = msg || "Onbekende fout";\n');
  doc.write('      errorMessage.classList.add("visible");\n');
  doc.write('      setTimeout(function() { errorMessage.classList.remove("visible"); }, 5000);\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    function updateProgress(pct) {\n');
  doc.write('      progressFill.style.width = Math.min(pct, 100) + "%";\n');
  doc.write('      loadingText.textContent = "Laden... " + Math.round(Math.min(pct, 100)) + "%";\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    function loadGame(alias) {\n');
  doc.write('      currentAlias = alias;\n');
  doc.write('      errorMessage.classList.remove("visible");\n');
  doc.write('      loadingOverlay.classList.remove("hidden");\n');
  doc.write('      updateProgress(0);\n');
  doc.write('      setStatus("loading", "Laden...");\n');
  doc.write('      \n');
  doc.write('      var gid = "game-" + Date.now() + "-" + Math.random().toString(36).substr(2, 6);\n');
  doc.write('      currentGid = gid;\n');
  doc.write('      \n');
  doc.write('      gameContainer.setAttribute("alias", alias);\n');
  doc.write('      gameContainer.setAttribute("gid", gid);\n');
  doc.write('      \n');
  doc.write('      setTimeout(function() {\n');
  doc.write('        if (window.nex && window.nex[gid]) {\n');
  doc.write('          var game = window.nex[gid];\n');
  doc.write('          game.on("progress", function(data) { updateProgress(data.progress || 0); });\n');
  doc.write('          game.on("ready", function() {\n');
  doc.write('            updateProgress(100);\n');
  doc.write('            loadingText.textContent = "Klaar! 🎮";\n');
  doc.write('            setStatus("ready", "\\"" + alias + "\\" is klaar!");\n');
  doc.write('            setTimeout(function() {\n');
  doc.write('              loadingOverlay.classList.add("hidden");\n');
  doc.write('              game.start();\n');
  doc.write('            }, 400);\n');
  doc.write('          });\n');
  doc.write('          game.on("error", function(err) {\n');
  doc.write('            loadingOverlay.classList.add("hidden");\n');
  doc.write('            setStatus("error", "Fout bij laden");\n');
  doc.write('            showError("Kan \\"" + alias + "\\" niet laden: " + (err.message || "Onbekende fout"));\n');
  doc.write('          });\n');
  doc.write('        } else {\n');
  doc.write('          setTimeout(function() {\n');
  doc.write('            loadingOverlay.classList.add("hidden");\n');
  doc.write('            setStatus("ready", "\\"" + alias + "\\" geladen");\n');
  doc.write('          }, 2000);\n');
  doc.write('        }\n');
  doc.write('      }, 100);\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    function resetGame() {\n');
  doc.write('      loadGame(currentAlias);\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    function loadRandomGame() {\n');
  doc.write('      if (window.nex && window.nex.metadata) {\n');
  doc.write('        var aliases = window.nex.metadata.getAllAliases();\n');
  doc.write('        if (aliases.length > 0) {\n');
  doc.write('          var random = aliases[Math.floor(Math.random() * aliases.length)];\n');
  doc.write('          loadGame(random);\n');
  doc.write('          searchInput.value = "";\n');
  doc.write('          filterGames("");\n');
  doc.write('        }\n');
  doc.write('      }\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    function filterGames(query) {\n');
  doc.write('      var cards = galleryGrid.querySelectorAll(".gallery-card");\n');
  doc.write('      var q = query.toLowerCase().trim();\n');
  doc.write('      cards.forEach(function(card) {\n');
  doc.write('        var alias = card.dataset.alias.toLowerCase();\n');
  doc.write('        var name = card.dataset.name.toLowerCase();\n');
  doc.write('        var match = !q || alias.indexOf(q) !== -1 || name.indexOf(q) !== -1;\n');
  doc.write('        card.style.display = match ? "" : "none";\n');
  doc.write('      });\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    function buildGallery() {\n');
  doc.write('      if (!window.nex || !window.nex.metadata) {\n');
  doc.write('        setTimeout(buildGallery, 500);\n');
  doc.write('        return;\n');
  doc.write('      }\n');
  doc.write('      \n');
  doc.write('      var allGames = window.nex.metadata.getAllMetadata();\n');
  doc.write('      galleryGrid.innerHTML = "";\n');
  doc.write('      \n');
  doc.write('      var gameKeys = Object.keys(allGames);\n');
  doc.write('      for (var i = 0; i < gameKeys.length; i++) {\n');
  doc.write('        var game = allGames[gameKeys[i]];\n');
  doc.write('        var card = document.createElement("div");\n');
  doc.write('        card.className = "gallery-card";\n');
  doc.write('        card.dataset.alias = game.alias;\n');
  doc.write('        card.dataset.name = game.name;\n');
  doc.write('        card.innerHTML = \'<img src="\' + game.img + \'" alt="\' + game.name + \'" loading="lazy" onerror="this.src=&apos;data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22400%22 height=%22300%22><rect fill=%22%231a1a2e%22 width=%22400%22 height=%22300%22/><text x=%2250%%22 y=%2250%%22 text-anchor=%22middle%22 dy=%22.3em%22 fill=%22%23666%22 font-size=%2230%22>🎮</text></svg>&apos;"> <div class="info"> <h3>\' + game.name + \'</h3> <div class="category">\' + (game.category || "Game") + \'</div> </div>\';\n');
  doc.write('        card.onclick = (function(gameAlias) {\n');
  doc.write('          return function() {\n');
  doc.write('            loadGame(gameAlias);\n');
  doc.write('            searchInput.value = "";\n');
  doc.write('            filterGames("");\n');
  doc.write('          };\n');
  doc.write('        })(game.alias);\n');
  doc.write('        galleryGrid.appendChild(card);\n');
  doc.write('      }\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    document.addEventListener("DOMContentLoaded", function() {\n');
  doc.write('      buildGallery();\n');
  doc.write('      setTimeout(function() { loadGame("2048"); }, 300);\n');
  doc.write('    });\n');
  doc.write('    \n');
  doc.write('    if (window.nex) {\n');
  doc.write('      window.nex.ready = window.nex.ready || function() {};\n');
  doc.write('      var origReady = window.nex.ready;\n');
  doc.write('      window.nex.ready = function() {\n');
  doc.write('        origReady();\n');
  doc.write('        buildGallery();\n');
  doc.write('      };\n');
  doc.write('    }\n');
  doc.write('    \n');
  doc.write('    console.log("🎮 Nex Game Platform geladen!");\n');
  doc.write('  <\/script>\n');
  doc.write('<\/body>\n');
  doc.write('<\/html>');
  doc.close();
})();
